PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "key_value" (
"collection" VARCHAR(128) NOT NULL DEFAULT '', 
"name" VARCHAR(128) NOT NULL DEFAULT '', 
"value" BLOB NOT NULL, 
 PRIMARY KEY ("collection", "name")
);
CREATE TABLE IF NOT EXISTS "config" (
"collection" VARCHAR(255) NOT NULL DEFAULT '', 
"name" VARCHAR(255) NOT NULL DEFAULT '', 
"data" BLOB NULL DEFAULT NULL, 
 PRIMARY KEY ("collection", "name")
);
CREATE TABLE IF NOT EXISTS "sequences" (
"value" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("value">= 0)
);
CREATE TABLE IF NOT EXISTS "users_data" (
"uid" INTEGER NOT NULL CHECK ("uid">= 0) DEFAULT 0, 
"module" VARCHAR(50) NOT NULL DEFAULT '', 
"name" VARCHAR(128) NOT NULL DEFAULT '', 
"value" BLOB NULL DEFAULT NULL, 
"serialized" INTEGER CHECK ("serialized">= 0) DEFAULT 0, 
 PRIMARY KEY ("uid", "module", "name")
);
CREATE TABLE IF NOT EXISTS "help_search_items" (
"sid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("sid">= 0), 
"section_plugin_id" VARCHAR(255) NOT NULL DEFAULT '', 
"permission" VARCHAR(255) NOT NULL DEFAULT '', 
"topic_id" VARCHAR(255) NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS "watchdog" (
"wid" INTEGER PRIMARY KEY AUTOINCREMENT, 
"uid" INTEGER NOT NULL CHECK ("uid">= 0) DEFAULT 0, 
"type" VARCHAR(64) NOT NULL DEFAULT '', 
"message" TEXT NOT NULL, 
"variables" BLOB NOT NULL, 
"severity" INTEGER NOT NULL CHECK ("severity">= 0) DEFAULT 0, 
"link" TEXT NULL DEFAULT NULL, 
"location" TEXT NOT NULL, 
"referer" TEXT NULL DEFAULT NULL, 
"hostname" VARCHAR(128) NOT NULL DEFAULT '', 
"timestamp" INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS "search_dataset" (
"sid" INTEGER NOT NULL CHECK ("sid">= 0) DEFAULT 0, 
"langcode" VARCHAR(12) NOT NULL DEFAULT '', 
"type" VARCHAR(64) NOT NULL, 
"data" TEXT NOT NULL, 
"reindex" INTEGER NOT NULL CHECK ("reindex">= 0) DEFAULT 0, 
 PRIMARY KEY ("sid", "langcode", "type")
);
CREATE TABLE IF NOT EXISTS "search_index" (
"word" VARCHAR(50) NOT NULL DEFAULT '', 
"sid" INTEGER NOT NULL CHECK ("sid">= 0) DEFAULT 0, 
"langcode" VARCHAR(12) NOT NULL DEFAULT '', 
"type" VARCHAR(64) NOT NULL, 
"score" FLOAT NULL DEFAULT NULL, 
 PRIMARY KEY ("word", "sid", "langcode", "type")
);
CREATE TABLE IF NOT EXISTS "search_total" (
"word" VARCHAR(50) NOT NULL DEFAULT '', 
"count" FLOAT NULL DEFAULT NULL, 
 PRIMARY KEY ("word")
);
CREATE TABLE IF NOT EXISTS "file_usage" (
"fid" INTEGER NOT NULL CHECK ("fid">= 0), 
"module" VARCHAR(50) NOT NULL DEFAULT '', 
"type" VARCHAR(64) NOT NULL DEFAULT '', 
"id" VARCHAR(64) NOT NULL DEFAULT 0, 
"count" INTEGER NOT NULL CHECK ("count">= 0) DEFAULT 0, 
 PRIMARY KEY ("fid", "type", "id", "module")
);
CREATE TABLE IF NOT EXISTS "users" (
"uid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("uid">= 0), 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "users_field_data" (
"uid" INTEGER NOT NULL CHECK ("uid">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"preferred_langcode" VARCHAR(12) NULL DEFAULT NULL, 
"preferred_admin_langcode" VARCHAR(12) NULL DEFAULT NULL, 
"name" VARCHAR(60) COLLATE NOCASE_UTF8 NOT NULL, 
"pass" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"mail" VARCHAR(254) NULL DEFAULT NULL, 
"timezone" VARCHAR(32) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"status" INTEGER NULL DEFAULT NULL, 
"created" INTEGER NOT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"access" INTEGER NOT NULL, 
"login" INTEGER NULL DEFAULT NULL, 
"init" VARCHAR(254) NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
 PRIMARY KEY ("uid", "langcode")
);
CREATE TABLE IF NOT EXISTS "user__roles" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"roles_target_id" VARCHAR(255) NOT NULL, 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "path_alias" (
"id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id">= 0), 
"revision_id" INTEGER NULL CHECK ("revision_id">= 0) DEFAULT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"path" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"alias" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"status" INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS "path_alias_revision" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"path" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"alias" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"status" INTEGER NOT NULL, 
"revision_default" INTEGER NULL DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "block_content" (
"id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id">= 0), 
"revision_id" INTEGER NULL CHECK ("revision_id">= 0) DEFAULT NULL, 
"type" VARCHAR(32) NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "block_content_revision" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"revision_user" INTEGER NULL CHECK ("revision_user">= 0) DEFAULT NULL, 
"revision_created" INTEGER NULL DEFAULT NULL, 
"revision_log" TEXT NULL DEFAULT NULL, 
"revision_default" INTEGER NULL DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "block_content_field_data" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"type" VARCHAR(32) NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"info" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"reusable" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("id", "langcode")
);
CREATE TABLE IF NOT EXISTS "block_content_field_revision" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"info" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("revision_id", "langcode")
);
CREATE TABLE IF NOT EXISTS "file_managed" (
"fid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("fid">= 0), 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"uid" INTEGER NULL CHECK ("uid">= 0) DEFAULT NULL, 
"filename" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"uri" VARCHAR(255) NOT NULL, 
"filemime" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"filesize" INTEGER NULL CHECK ("filesize">= 0) DEFAULT NULL, 
"status" INTEGER NOT NULL, 
"created" INTEGER NULL DEFAULT NULL, 
"changed" INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS "comment_entity_statistics" (
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0) DEFAULT 0, 
"entity_type" VARCHAR(32) NOT NULL DEFAULT 'node', 
"field_name" VARCHAR(32) NOT NULL DEFAULT '', 
"cid" INTEGER NOT NULL DEFAULT 0, 
"last_comment_timestamp" INTEGER NOT NULL DEFAULT 0, 
"last_comment_name" VARCHAR(60) NULL DEFAULT NULL, 
"last_comment_uid" INTEGER NOT NULL CHECK ("last_comment_uid">= 0) DEFAULT 0, 
"comment_count" INTEGER NOT NULL CHECK ("comment_count">= 0) DEFAULT 0, 
 PRIMARY KEY ("entity_id", "entity_type", "field_name")
);
CREATE TABLE IF NOT EXISTS "node_access" (
"nid" INTEGER NOT NULL CHECK ("nid">= 0) DEFAULT 0, 
"langcode" VARCHAR(12) NOT NULL DEFAULT '', 
"fallback" INTEGER NOT NULL CHECK ("fallback">= 0) DEFAULT 1, 
"gid" INTEGER NOT NULL CHECK ("gid">= 0) DEFAULT 0, 
"realm" VARCHAR(255) NOT NULL DEFAULT '', 
"grant_view" INTEGER NOT NULL CHECK ("grant_view">= 0) DEFAULT 0, 
"grant_update" INTEGER NOT NULL CHECK ("grant_update">= 0) DEFAULT 0, 
"grant_delete" INTEGER NOT NULL CHECK ("grant_delete">= 0) DEFAULT 0, 
 PRIMARY KEY ("nid", "gid", "realm", "langcode")
);
CREATE TABLE IF NOT EXISTS "history" (
"uid" INTEGER NOT NULL DEFAULT 0, 
"nid" INTEGER NOT NULL CHECK ("nid">= 0) DEFAULT 0, 
"timestamp" INTEGER NOT NULL DEFAULT 0, 
 PRIMARY KEY ("uid", "nid")
);
CREATE TABLE IF NOT EXISTS "shortcut_set_users" (
"uid" INTEGER NOT NULL CHECK ("uid">= 0) DEFAULT 0, 
"set_name" VARCHAR(32) NOT NULL DEFAULT '', 
 PRIMARY KEY ("uid")
);
CREATE TABLE IF NOT EXISTS "comment" (
"cid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("cid">= 0), 
"comment_type" VARCHAR(32) NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "comment_field_data" (
"cid" INTEGER NOT NULL CHECK ("cid">= 0), 
"comment_type" VARCHAR(32) NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"uid" INTEGER NOT NULL CHECK ("uid">= 0), 
"pid" INTEGER NULL CHECK ("pid">= 0) DEFAULT NULL, 
"entity_id" INTEGER NULL CHECK ("entity_id">= 0) DEFAULT NULL, 
"subject" VARCHAR(64) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"name" VARCHAR(60) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"mail" VARCHAR(254) NULL DEFAULT NULL, 
"homepage" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"hostname" VARCHAR(128) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"created" INTEGER NOT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"thread" VARCHAR(255) COLLATE NOCASE_UTF8 NOT NULL, 
"entity_type" VARCHAR(32) COLLATE NOCASE_UTF8 NOT NULL, 
"field_name" VARCHAR(32) COLLATE NOCASE_UTF8 NOT NULL, 
"default_langcode" INTEGER NOT NULL, 
 PRIMARY KEY ("cid", "langcode")
);
CREATE TABLE IF NOT EXISTS "node" (
"nid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("nid">= 0), 
"vid" INTEGER NULL CHECK ("vid">= 0) DEFAULT NULL, 
"type" VARCHAR(32) NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "node_revision" (
"nid" INTEGER NOT NULL CHECK ("nid">= 0), 
"vid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("vid">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"revision_uid" INTEGER NULL CHECK ("revision_uid">= 0) DEFAULT NULL, 
"revision_timestamp" INTEGER NULL DEFAULT NULL, 
"revision_log" TEXT NULL DEFAULT NULL, 
"revision_default" INTEGER NULL DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "node_field_data" (
"nid" INTEGER NOT NULL CHECK ("nid">= 0), 
"vid" INTEGER NOT NULL CHECK ("vid">= 0), 
"type" VARCHAR(32) NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"uid" INTEGER NOT NULL CHECK ("uid">= 0), 
"title" VARCHAR(255) COLLATE NOCASE_UTF8 NOT NULL, 
"created" INTEGER NOT NULL, 
"changed" INTEGER NOT NULL, 
"promote" INTEGER NOT NULL, 
"sticky" INTEGER NOT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("nid", "langcode")
);
CREATE TABLE IF NOT EXISTS "node_field_revision" (
"nid" INTEGER NOT NULL CHECK ("nid">= 0), 
"vid" INTEGER NOT NULL CHECK ("vid">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"uid" INTEGER NOT NULL CHECK ("uid">= 0), 
"title" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"created" INTEGER NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"promote" INTEGER NULL DEFAULT NULL, 
"sticky" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("vid", "langcode")
);
CREATE TABLE IF NOT EXISTS "menu_link_content" (
"id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id">= 0), 
"revision_id" INTEGER NULL CHECK ("revision_id">= 0) DEFAULT NULL, 
"bundle" VARCHAR(32) COLLATE NOCASE_UTF8 NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "menu_link_content_revision" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"revision_user" INTEGER NULL CHECK ("revision_user">= 0) DEFAULT NULL, 
"revision_created" INTEGER NULL DEFAULT NULL, 
"revision_log_message" TEXT NULL DEFAULT NULL, 
"revision_default" INTEGER NULL DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "menu_link_content_data" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"bundle" VARCHAR(32) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"enabled" INTEGER NOT NULL, 
"title" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"description" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"menu_name" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"link__uri" VARCHAR(2048) NULL DEFAULT NULL, 
"link__title" VARCHAR(255) NULL DEFAULT NULL, 
"link__options" BLOB NULL DEFAULT NULL, 
"external" INTEGER NULL DEFAULT NULL, 
"rediscover" INTEGER NULL DEFAULT NULL, 
"weight" INTEGER NULL DEFAULT NULL, 
"expanded" INTEGER NULL DEFAULT NULL, 
"parent" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("id", "langcode")
);
CREATE TABLE IF NOT EXISTS "menu_link_content_field_revision" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"enabled" INTEGER NOT NULL, 
"title" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"description" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"link__uri" VARCHAR(2048) NULL DEFAULT NULL, 
"link__title" VARCHAR(255) NULL DEFAULT NULL, 
"link__options" BLOB NULL DEFAULT NULL, 
"external" INTEGER NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("revision_id", "langcode")
);
CREATE TABLE IF NOT EXISTS "shortcut" (
"id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id">= 0), 
"shortcut_set" VARCHAR(32) NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "shortcut_field_data" (
"id" INTEGER NOT NULL CHECK ("id">= 0), 
"shortcut_set" VARCHAR(32) NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"title" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"weight" INTEGER NULL DEFAULT NULL, 
"link__uri" VARCHAR(2048) NULL DEFAULT NULL, 
"link__title" VARCHAR(255) NULL DEFAULT NULL, 
"link__options" BLOB NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
 PRIMARY KEY ("id", "langcode")
);
CREATE TABLE IF NOT EXISTS "taxonomy_term_data" (
"tid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("tid">= 0), 
"revision_id" INTEGER NULL CHECK ("revision_id">= 0) DEFAULT NULL, 
"vid" VARCHAR(32) NOT NULL, 
"uuid" VARCHAR(128) COLLATE NOCASE_UTF8 NOT NULL, 
"langcode" VARCHAR(12) NOT NULL
);
CREATE TABLE IF NOT EXISTS "taxonomy_term_revision" (
"tid" INTEGER NOT NULL CHECK ("tid">= 0), 
"revision_id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"revision_user" INTEGER NULL CHECK ("revision_user">= 0) DEFAULT NULL, 
"revision_created" INTEGER NULL DEFAULT NULL, 
"revision_log_message" TEXT NULL DEFAULT NULL, 
"revision_default" INTEGER NULL DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "taxonomy_term_field_data" (
"tid" INTEGER NOT NULL CHECK ("tid">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"vid" VARCHAR(32) NOT NULL, 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"name" VARCHAR(255) COLLATE NOCASE_UTF8 NOT NULL, 
"description__value" TEXT NULL DEFAULT NULL, 
"description__format" VARCHAR(255) NULL DEFAULT NULL, 
"weight" INTEGER NOT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("tid", "langcode")
);
CREATE TABLE IF NOT EXISTS "taxonomy_term_field_revision" (
"tid" INTEGER NOT NULL CHECK ("tid">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(12) NOT NULL, 
"status" INTEGER NOT NULL, 
"name" VARCHAR(255) COLLATE NOCASE_UTF8 NULL DEFAULT NULL, 
"description__value" TEXT NULL DEFAULT NULL, 
"description__format" VARCHAR(255) NULL DEFAULT NULL, 
"changed" INTEGER NULL DEFAULT NULL, 
"default_langcode" INTEGER NOT NULL, 
"revision_translation_affected" INTEGER NULL DEFAULT NULL, 
 PRIMARY KEY ("revision_id", "langcode")
);
CREATE TABLE IF NOT EXISTS "taxonomy_index" (
"nid" INTEGER NOT NULL CHECK ("nid">= 0) DEFAULT 0, 
"tid" INTEGER NOT NULL CHECK ("tid">= 0) DEFAULT 0, 
"status" INTEGER NOT NULL DEFAULT 1, 
"sticky" INTEGER NULL DEFAULT 0, 
"created" INTEGER NOT NULL DEFAULT 0, 
 PRIMARY KEY ("nid", "tid")
);
CREATE TABLE IF NOT EXISTS "taxonomy_term__parent" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"parent_target_id" INTEGER NOT NULL CHECK ("parent_target_id">= 0), 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "taxonomy_term_revision__parent" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"parent_target_id" INTEGER NOT NULL CHECK ("parent_target_id">= 0), 
 PRIMARY KEY ("entity_id", "revision_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "comment__comment_body" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"comment_body_value" TEXT NOT NULL, 
"comment_body_format" VARCHAR(255) NULL DEFAULT NULL, 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "router" (
"name" VARCHAR(255) NOT NULL DEFAULT '', 
"path" VARCHAR(255) NOT NULL DEFAULT '', 
"pattern_outline" VARCHAR(255) NOT NULL DEFAULT '', 
"fit" INTEGER NOT NULL DEFAULT 0, 
"route" BLOB DEFAULT NULL, 
"number_parts" INTEGER NOT NULL DEFAULT 0, 
"alias" VARCHAR(255) DEFAULT NULL, 
 PRIMARY KEY ("name")
);
CREATE TABLE IF NOT EXISTS "menu_tree" (
"menu_name" VARCHAR(32) NOT NULL DEFAULT '', 
"mlid" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("mlid">= 0), 
"id" VARCHAR(255) NOT NULL, 
"parent" VARCHAR(255) NOT NULL DEFAULT '', 
"route_name" VARCHAR(255) DEFAULT NULL, 
"route_param_key" VARCHAR(2048) DEFAULT NULL, 
"route_parameters" BLOB NULL DEFAULT NULL, 
"url" VARCHAR(2048) NOT NULL DEFAULT '', 
"title" BLOB NULL DEFAULT NULL, 
"description" BLOB NULL DEFAULT NULL, 
"class" TEXT NULL DEFAULT NULL, 
"options" BLOB NULL DEFAULT NULL, 
"provider" VARCHAR(50) NOT NULL DEFAULT 'system', 
"enabled" INTEGER NOT NULL DEFAULT 1, 
"discovered" INTEGER NOT NULL DEFAULT 0, 
"expanded" INTEGER NOT NULL DEFAULT 0, 
"weight" INTEGER NOT NULL DEFAULT 0, 
"metadata" BLOB NULL DEFAULT NULL, 
"has_children" INTEGER NOT NULL DEFAULT 0, 
"depth" INTEGER NOT NULL DEFAULT 0, 
"p1" INTEGER NOT NULL CHECK ("p1">= 0) DEFAULT 0, 
"p2" INTEGER NOT NULL CHECK ("p2">= 0) DEFAULT 0, 
"p3" INTEGER NOT NULL CHECK ("p3">= 0) DEFAULT 0, 
"p4" INTEGER NOT NULL CHECK ("p4">= 0) DEFAULT 0, 
"p5" INTEGER NOT NULL CHECK ("p5">= 0) DEFAULT 0, 
"p6" INTEGER NOT NULL CHECK ("p6">= 0) DEFAULT 0, 
"p7" INTEGER NOT NULL CHECK ("p7">= 0) DEFAULT 0, 
"p8" INTEGER NOT NULL CHECK ("p8">= 0) DEFAULT 0, 
"p9" INTEGER NOT NULL CHECK ("p9">= 0) DEFAULT 0, 
"form_class" VARCHAR(255) DEFAULT NULL
);
CREATE TABLE IF NOT EXISTS "node__field_image" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"field_image_target_id" INTEGER NOT NULL CHECK ("field_image_target_id">= 0), 
"field_image_alt" VARCHAR(512) NULL DEFAULT NULL, 
"field_image_title" VARCHAR(1024) NULL DEFAULT NULL, 
"field_image_width" INTEGER NULL CHECK ("field_image_width">= 0) DEFAULT NULL, 
"field_image_height" INTEGER NULL CHECK ("field_image_height">= 0) DEFAULT NULL, 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node_revision__field_image" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"field_image_target_id" INTEGER NOT NULL CHECK ("field_image_target_id">= 0), 
"field_image_alt" VARCHAR(512) NULL DEFAULT NULL, 
"field_image_title" VARCHAR(1024) NULL DEFAULT NULL, 
"field_image_width" INTEGER NULL CHECK ("field_image_width">= 0) DEFAULT NULL, 
"field_image_height" INTEGER NULL CHECK ("field_image_height">= 0) DEFAULT NULL, 
 PRIMARY KEY ("entity_id", "revision_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node__comment" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"comment_status" INTEGER NOT NULL DEFAULT 0, 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node_revision__comment" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"comment_status" INTEGER NOT NULL DEFAULT 0, 
 PRIMARY KEY ("entity_id", "revision_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node__field_tags" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"field_tags_target_id" INTEGER NOT NULL CHECK ("field_tags_target_id">= 0), 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node_revision__field_tags" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"field_tags_target_id" INTEGER NOT NULL CHECK ("field_tags_target_id">= 0), 
 PRIMARY KEY ("entity_id", "revision_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node__body" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
"entity_id" INTEGER NOT NULL CHECK ("entity_id">= 0), 
"revision_id" INTEGER NOT NULL CHECK ("revision_id">= 0), 
"langcode" VARCHAR(32) NOT NULL DEFAULT '', 
"delta" INTEGER NOT NULL CHECK ("delta">= 0), 
"body_value" TEXT NOT NULL, 
"body_summary" TEXT NULL DEFAULT NULL, 
"body_format" VARCHAR(255) NULL DEFAULT NULL, 
 PRIMARY KEY ("entity_id", "deleted", "delta", "langcode")
);
CREATE TABLE IF NOT EXISTS "node_revision__body" (
"bundle" VARCHAR(128) NOT NULL DEFAULT '', 
"deleted" INTEGER NOT NULL DEFAULT 0, 
